import {t,localizedName} from './i18n.js';
const compactLayout=matchMedia('(max-width:760px)');
const componentDetails=document.querySelector('.component-disclosure');
componentDetails.open=!compactLayout.matches;
compactLayout.addEventListener('change',e=>componentDetails.open=!e.matches);
import {markingSpec} from './engineering-markings.js';
import {sourceModel} from './engineering-models.js';
import {DEFAULT_SCENE,validateScene} from './engine.js';
const $=id=>document.getElementById(id);let key=new URLSearchParams(location.search).get('board')==='rp2040'?'rp2040':'snowflake',mode='3d',side='F',selected=null,assembly=false,viewer=null,viewerError=false,loadID=0,buildQueue=Promise.resolve(),drawSvg=null,drawBox=null,toastTimer;
let data={};let project={boards:[{id:1,x:-92,y:15,rotation:0},{id:2,x:0,y:-25,rotation:0},{id:3,x:92,y:15,rotation:0}],scene:structuredClone(DEFAULT_SCENE)};
try{const p=JSON.parse(localStorage.getItem('snowflake-studio-v1'));if(p&&Array.isArray(p.boards)&&p.boards.length>0&&p.boards.length<=12&&p.boards.every(b=>['x','y','rotation'].every(k=>Number.isFinite(b[k])&&Math.abs(b[k])<=10000))){validateScene(p.scene,p.boards.length);project=p;}}catch{}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
const htmlEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function download(blob,name){const u=typeof blob==='string'?blob:URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();if(typeof blob!=='string')setTimeout(()=>URL.revokeObjectURL(u),1000);}
function boardInfo(){const d=data[key],[x,y,X,Y]=d.bounds;$('viewTitle').textContent=d.name;$('boardFacts').innerHTML=`<div><b>${(X-x).toFixed(1)} × ${(Y-y).toFixed(1)} mm</b><small>真实板框尺寸</small></div><div><b>${d.thickness} mm</b><small>工程板厚</small></div><div><b>${d.tracks.length} 段走线</b><small>双面 PCB · ${d.vias.length} 个过孔</small></div><div><b>${d.components.filter(f=>f.pads.length).length} 个器件</b><small>不含图形标志</small></div>`;$('zipDownload').href=`engineering/${key}-kicad.zip`;$('componentCount').textContent=d.components.filter(f=>f.pads.length).length;$('sceneName').dataset.i18nSkip='';$('sceneName').textContent=t('灯效')+': '+localizedName(project.scene.name);document.querySelectorAll('[data-board]').forEach(b=>b.classList.toggle('selected',b.dataset.board===key));listParts();}
function listParts(){let q=$('componentSearch').value.toLowerCase(),parts=data[key].components.filter(f=>f.pads.length&&[f.ref,f.value,f.footprint,...f.pads.map(p=>p.net)].join(' ').toLowerCase().includes(q)).sort((a,b)=>a.ref.localeCompare(b.ref,undefined,{numeric:true}));$('componentList').replaceChildren();for(const f of parts){let b=document.createElement('button');b.innerHTML=`<b>${htmlEscape(f.ref)}</b><span>${htmlEscape(f.value)}</span><em>${f.side==='F'?'正面':'背面'}</em>`;b.classList.toggle('selected',selected?.ref===f.ref);b.onclick=()=>selectPart(f,key,true);$('componentList').append(b);}if(!parts.length)$('componentList').textContent='没有匹配的器件';}
async function selectPart(f,board,fromList=false){if(board!==key){key=board;boardInfo();}selected=f;listParts();$('selectionInfo').innerHTML=`<div class="eyebrow">COMPONENT / ${htmlEscape(f.side==='F'?'TOP':'BOTTOM')}</div><h3>${htmlEscape(f.ref)} · ${htmlEscape(f.value)}</h3><p class="part-meta">${htmlEscape(f.footprint)}<br>X ${f.at[0]} mm · Y ${f.at[1]} mm · 旋转 ${f.at[2]}°</p>${sourceModel(f,board)?`<p class="part-meta">${f.ref==='J1'?'3D：工程关联 GCT USB4105 模型 · 原始偏移 Y −1.25 mm；PCB 封装名为 Palconn UTC16-G，两者型号不同，尚未核对实物。':'3D：工程指定 KiCad 模型 · 2×6 排针 · 按原始旋转与偏移安装'}</p>`:''}${markingSpec(f)?`<p class="part-meta">${htmlEscape(markingSpec(f).note)}</p>`:''}<div class="pin-list">${f.pads.map(p=>`<div class="pin-row"><b>Pin ${htmlEscape(p.number||'—')}</b><span>${htmlEscape(p.net||'无网络')}${sourceModel(f,board)&&f.ref==='J2'?(p.layers.includes('F.Cu')?' · 正面焊盘':' · 背面焊盘'):''}</span></div>`).join('')}</div>`;viewer?.select(f.ref,board);if(fromList&&mode==='3d'&&side!==f.side){side=f.side;controls();viewer?.setSide(side);}if(fromList&&mode==='pcb'&&side!==f.side){side=f.side;await refresh();}highlight();}
function highlight(){if(!drawSvg)return;drawSvg.querySelectorAll('[data-ref]').forEach(e=>{let active=e.dataset.ref===selected?.ref;e.setAttribute('stroke',active?'#f6dc6c':'transparent');e.setAttribute('fill',active?'#f6dc6c22':'transparent');});}
function controls(){document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));document.querySelectorAll('[data-side]').forEach(b=>b.classList.toggle('selected',b.dataset.side===side));$('threeMount').hidden=mode!=='3d';$('drawingMount').hidden=!['pcb','schematic'].includes(mode);$('productMount').hidden=mode!=='product';$('productCaption').hidden=mode!=='product';$('threeOptions').hidden=mode!=='3d';$('pcbOptions').hidden=mode!=='pcb';$('sideButtons').hidden=!['3d','pcb'].includes(mode);$('viewHint').textContent=mode==='3d'?'拖动旋转 · 滚轮缩放 · 右键平移':mode==='product'?'AI 辅助产品概念渲染':'拖动平移 · 滚轮缩放 · 点击器件';$('viewportLabel').textContent=mode==='3d'?'真实板框 / 参数化元件外观':mode==='pcb'?'焊盘 · 走线 · 丝印 / 原工程数据':mode==='schematic'?'原理图只读预览 / 内嵌符号与连接线':'产品概念效果图 / 非实物照片';$('zoomIn').hidden=$('zoomOut').hidden=$('fit').hidden=mode==='product';$('animateLights').disabled=key==='rp2040'&&!assembly;$('usbView').hidden=key!=='rp2040'||assembly;}
async function refresh(){let id=++loadID;controls();$('loading').hidden=false;$('loading').textContent='正在载入工程模型…';if(viewer)viewer.active=mode==='3d';try{
 if(mode==='product'){await $('productImage').decode();}
 else if(mode==='3d'){
  
  if(!viewer){try{const {Engineering3D}=await import('./engineering-3d.js');viewer=new Engineering3D($('threeMount'),(f,b)=>selectPart(f,b));}catch(e){const {EngineeringCanvas}=await import('./engineering-canvas.js');viewer=new EngineeringCanvas($('threeMount'),(f,b)=>selectPart(f,b));}}
  const buildKey=key,buildColor=$('materialColor').value,buildAssembly=assembly;buildQueue=buildQueue.catch(()=>{}).then(()=>viewer.build(data,buildKey,buildColor,project,buildAssembly));await buildQueue;if(id!==loadID)return;viewer.animate=$('animateLights').checked;viewer.active=true;viewer.setSide(side);viewer.resize();if(viewer.compatibility)$('viewportLabel').textContent='兼容立体视图 / 真实板框与参数化封装';if(selected)viewer.select(selected.ref,key);
 }else{const path=`engineering/${key}-${mode==='pcb'?side:'schematic'}.svg`;const text=await(await fetch(path)).text();if(id!==loadID)return;$('drawingMount').innerHTML=text;drawSvg=$('drawingMount').querySelector('svg');drawSvg.setAttribute('preserveAspectRatio','xMidYMid meet');drawBox=drawSvg.getAttribute('viewBox').split(' ').map(Number);if(mode==='pcb'){if(side==='B'){const group=document.createElementNS('http://www.w3.org/2000/svg','g');group.id='mirror';const center=(data[key].bounds[0]+data[key].bounds[2])/2;group.setAttribute('transform',`translate(${2*center},0) scale(-1,1)`);while(drawSvg.firstChild)group.append(drawSvg.firstChild);drawSvg.append(group);}const host=drawSvg.querySelector('#mirror')||drawSvg;let hit=document.createElementNS('http://www.w3.org/2000/svg','g');hit.id='interactiveParts';for(const f of data[key].components){if(f.side!==side||!f.pads.length)continue;const [x,y,X,Y]=f.fabBounds,r=document.createElementNS('http://www.w3.org/2000/svg','rect');r.setAttribute('x',x-.3);r.setAttribute('y',y-.3);r.setAttribute('width',X-x+.6);r.setAttribute('height',Y-y+.6);r.setAttribute('transform',`translate(${f.at[0]},${f.at[1]}) rotate(${-f.at[2]})`);r.setAttribute('stroke-width','.3');r.setAttribute('data-ref',f.ref);r.style.cursor='pointer';r.addEventListener('click',e=>{if(dragMoved)return;e.stopPropagation();selectPart(f,key);});const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=f.ref+' · '+f.value;r.append(title);hit.append(r);}host.append(hit);applyLayers();highlight();}applyBox();}
 if(id===loadID)$('loading').hidden=true;
 }catch(e){if(id===loadID){$('loading').textContent='预览暂时无法载入。'+(mode==='3d'?'可切换 PCB / 原理图查看工程。':'请刷新后重试。');toast(e.message||'载入失败');}}}
function applyLayers(){document.querySelectorAll('[data-layer]').forEach(c=>{const el=drawSvg?.querySelector('#'+c.dataset.layer);if(el)el.style.display=c.checked?'':'none';});const el=drawSvg?.querySelector('#interactiveParts');if(el)el.style.display=$('showRefs').checked?'':'none';}
function applyBox(){drawSvg?.setAttribute('viewBox',drawBox.join(' '));}
function zoom(f){if(mode==='3d')viewer?.zoom(f);else if(drawBox){const [x,y,w,h]=drawBox;let next=Math.max(.03,Math.min(20,w*f/(mode==='pcb'?(data[key].bounds[2]-data[key].bounds[0]+6):297)));let nw=next*(mode==='pcb'?(data[key].bounds[2]-data[key].bounds[0]+6):297),nh=h*nw/w;drawBox=[x+(w-nw)/2,y+(h-nh)/2,nw,nh];applyBox();}}
let dragStart=null,dragMoved=false;$('drawingMount').addEventListener('pointerdown',e=>{if(!drawSvg||e.button!==0)return;dragStart={x:e.clientX,y:e.clientY,box:[...drawBox]};dragMoved=false;});window.addEventListener('pointermove',e=>{if(!dragStart||!drawSvg)return;let dx=e.clientX-dragStart.x,dy=e.clientY-dragStart.y;if(Math.hypot(dx,dy)>4)dragMoved=true;let r=drawSvg.getBoundingClientRect(),scale=Math.max(dragStart.box[2]/r.width,dragStart.box[3]/r.height);drawBox=[dragStart.box[0]-dx*scale,dragStart.box[1]-dy*scale,dragStart.box[2],dragStart.box[3]];applyBox();});window.addEventListener('pointerup',()=>{dragStart=null;});window.addEventListener('pointercancel',()=>{dragStart=null;});$('drawingMount').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.12:.89);},{passive:false});
$('componentSearch').oninput=listParts;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;refresh();});document.querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{key=b.dataset.board;selected=null;$('selectionInfo').innerHTML='<div class="eyebrow">DETAILS</div><h3>点选器件，查看封装与网络</h3><p>可在左侧索引或工程视图中选择器件。</p>';assembly=false;$('assemblyBtn').classList.remove('selected');$('materialColor').value=key==='snowflake'?'white':'green';$('componentSearch').value='';boardInfo();refresh();});document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{side=b.dataset.side;if(mode==='3d'){controls();viewer?.setSide(side);}else refresh();});document.querySelectorAll('[data-layer]').forEach(c=>c.onchange=applyLayers);$('showRefs').onchange=applyLayers;$('materialColor').onchange=refresh;$('animateLights').onchange=()=>{if(viewer)viewer.animate=$('animateLights').checked;};$('autoRotate').onchange=()=>{if(viewer)viewer.controls.autoRotate=$('autoRotate').checked;};$('assemblyBtn').onclick=()=>{assembly=!assembly;$('assemblyBtn').classList.toggle('selected',assembly);refresh();};$('usbView').onclick=()=>{side='F';controls();viewer?.focusUSB();};$('zoomIn').onclick=()=>zoom(.8);$('zoomOut').onclick=()=>zoom(1.25);$('fit').onclick=()=>mode==='3d'?viewer?.fit(side):refresh();$('exportView').onclick=async()=>{if(mode==='3d'&&viewer)download(await viewer.capture(),`${key}-3d.png`);else if(mode==='product'){download(await(await fetch('engineering/product-render.png?v=markings2')).blob(),'snowflake-product-render.png');}else if(drawSvg)download(new Blob([new XMLSerializer().serializeToString(drawSvg)],{type:'image/svg+xml'}),`${key}-${mode}-${side}.svg`);};
try{const all=await Promise.all(['snowflake','rp2040'].map(async k=>[k,await(await fetch(`engineering/${k}.json`)).json()]));data=Object.fromEntries(all);$('materialColor').value=key==='snowflake'?'white':'green';boardInfo();await refresh();}catch(e){$('loading').textContent='工程数据载入失败，请刷新后重试。';toast(e.message);}

window.addEventListener('languagechange',()=>{if(data[key])boardInfo();});
